// Clean-room TSVC s235 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s235_fused_vector_matrix_recurrence(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<15||length>153{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];if !(2..=8).contains(&nr){return -1;}let n=nr as usize;let nn=n*n;if length!=1+3*n+2*nn{return -1;}let(mut a,mut b,mut c)=([0i64;8],[0i64;8],[0i64;8]);let(mut aa,mut bb)=([0i64;64],[0i64;64]);let mut p=1;for i in 0..n{let x=v[p];p+=1;if !(-1..=1).contains(&x){return -1;}a[i]=x;}for i in 0..n{let x=v[p];p+=1;if !(-1..=1).contains(&x){return -1;}b[i]=x;}for i in 0..n{let x=v[p];p+=1;if !(-1..=1).contains(&x){return -1;}c[i]=x;}for i in 0..nn{let x=v[p];p+=1;if !(-1..=1).contains(&x){return -1;}aa[i]=x;}for i in 0..nn{let x=v[p];p+=1;if !(-1..=1).contains(&x){return -1;}bb[i]=x;}if output.is_null()||capacity<8*(n+nn){return -2;}for col in 0..n{a[col]+=b[col]*c[col];for row in 1..n{let k=row*n+col;aa[k]=aa[k-n]+bb[k]*a[col];}}for i in 0..n{for j in 0..8{output.add(8*i+j).write(((a[i]as u64)>>(8*j))as u8);}}for i in 0..nn{for j in 0..8{output.add(8*(n+i)+j).write(((aa[i]as u64)>>(8*j))as u8);}}(n+nn)as i64}
